CREATE TABLE IF NOT EXISTS roles (id TINYINT PRIMARY KEY, name VARCHAR(30) NOT NULL UNIQUE);
INSERT INTO roles (id,name) VALUES (1,'administrator'),(2,'security_officer'),(3,'resident') ON DUPLICATE KEY UPDATE name=VALUES(name);
CREATE TABLE IF NOT EXISTS residents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(120) NOT NULL, phone VARCHAR(30), unit_number VARCHAR(40), status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, role_id TINYINT NOT NULL, resident_id BIGINT UNSIGNED UNIQUE NULL, full_name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, session_version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(resident_id) REFERENCES residents(id));
CREATE TABLE IF NOT EXISTS visits (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, visitor_name VARCHAR(120) NOT NULL, host_resident_id BIGINT UNSIGNED NOT NULL, purpose VARCHAR(250) NOT NULL, time_in DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, time_out DATETIME NULL, recorded_by BIGINT UNSIGNED NOT NULL, FOREIGN KEY(host_resident_id) REFERENCES residents(id), FOREIGN KEY(recorded_by) REFERENCES users(id), INDEX(time_in), INDEX(host_resident_id));
CREATE TABLE IF NOT EXISTS incidents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(160) NOT NULL, description TEXT NOT NULL, category VARCHAR(60) NOT NULL, status ENUM('open','in_progress','resolved') NOT NULL DEFAULT 'open', reported_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(reported_by) REFERENCES users(id), INDEX(status), INDEX(created_at));
CREATE TABLE IF NOT EXISTS notices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(160) NOT NULL, body TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, subject_type VARCHAR(50), subject_id BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL, ip_hash CHAR(64) NOT NULL, succeeded BOOLEAN NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(email,created_at));
CREATE TABLE IF NOT EXISTS schema_migrations (name VARCHAR(190) PRIMARY KEY, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);